"""W(E7) orbit unions on the points of Q(6,q) (q prime): orbits of the reflection group generated by 7 vectors with
E7 Cartan Gram matrix (setup_e7.py q), self-compatible orbits (pairwise opposite), exact max-weight clique of
compatible orbits. Adapted from squad card r6/c7 (research/squads/d10D7-r6/c7/run_e7.py).  usage: run_e7q.py q"""
import sys, time, numpy as np
sys.path.insert(0, '/home/user/degree-diameter/research/d10D7/ovoid/e7')
import orb11
from orb11 import *
q = int(sys.argv[1]); orb11.CAP = q ** 3 + 1
t0 = time.time(); w = W(q)
simple, roots = load_e7(q)
perms = [w.refl_perm(v) for v in simple]
lab = orbits_from_perms(w.G.N, perms); sizes = np.bincount(lab)
print('q', q, 'orbits', len(sizes), 'smallest sizes', sorted(sizes.tolist())[:12], round(time.time() - t0, 1), flush=True)
members, S, A = sc_and_compat(w.G, lab)
print('self-compatible orbits', len(S), [int(sizes[o]) for o in S], flush=True)
if len(S):
    wgt, cl, done = best_union(members, S, A)
    print('best union', wgt, 'orbits', [int(sizes[o]) for o in cl], 'exact', done, flush=True)
    pts = sorted(int(p) for o in cl for p in members[o])
    open('/home/user/degree-diameter/research/d10D7/ovoid/e7/best_E7_q%d.txt' % q, 'w').write('\n'.join(map(str, pts)) + '\n')
print('done', round(time.time() - t0, 1))
